// A minimal in-memory registry: service name -> live instances.
type Instance struct {
	ID   string
	Addr string // host:port
}

type Registry struct {
	mu       sync.RWMutex
	services map[string][]Instance // keyed by service name
}

func NewRegistry() *Registry {
	return &Registry{services: make(map[string][]Instance)}
}

// Lookup resolves a service name into its live instances.
func (r *Registry) Lookup(name string) []Instance {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return append([]Instance(nil), r.services[name]...) // copy to avoid races
}

// Self-registration: the instance adds itself, then heartbeats.
func (r *Registry) Register(name string, inst Instance) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.services[name] = append(r.services[name], inst)
}

func selfRegister(reg *Registry, name, addr string) {
	inst := Instance{ID: addr, Addr: addr}
	reg.Register(name, inst) // instance registers ITSELF on startup
	// A real self-registering service also runs a heartbeat loop
	// so the registry knows it is still alive (see health checks).
}

// TTL-based health: each instance heartbeats; a reaper prunes stale ones.
type health struct {
	lastSeen time.Time
}

// Heartbeat refreshes an instance's TTL.
func (r *Registry) Heartbeat(name, id string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.health[name+"/"+id] = health{lastSeen: time.Now()}
}

// reap deregisters instances whose TTL has expired.
func (r *Registry) reap(name string, ttl time.Duration) {
	r.mu.Lock()
	defer r.mu.Unlock()
	live := r.services[name][:0]
	for _, inst := range r.services[name] {
		h := r.health[name+"/"+inst.ID]
		if time.Since(h.lastSeen) < ttl {
			live = append(live, inst) // keep only fresh instances
		}
	}
	r.services[name] = live // stale entries dropped -> no black-holing
}

// Client-side round-robin over instances resolved from the registry.
type RoundRobin struct {
	n uint64
}

// Pick returns the next instance, cycling evenly across all of them.
func (rr *RoundRobin) Pick(insts []Instance) (Instance, bool) {
	if len(insts) == 0 {
		return Instance{}, false // no live backends
	}
	i := atomic.AddUint64(&rr.n, 1) // atomic so concurrent callers stay balanced
	return insts[int(i)%len(insts)], true
}

// gRPC dials with client-side round-robin over a resolver's addresses.
func dialBalanced(target string) (*grpc.ClientConn, error) {
	// target like "myregistry:///payments" is handled by a custom resolver
	// that pushes the current instance addresses to gRPC.
	return grpc.NewClient(
		target,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		// round_robin balances each RPC across all resolved sub-connections
		grpc.WithDefaultServiceConfig(`{"loadBalancingConfig":[{"round_robin":{}}]}`),
	)
}

// A tiny gateway handler: route by path prefix, aggregate two backends.
func (g *Gateway) handle(w http.ResponseWriter, r *http.Request) {
	switch {
	case strings.HasPrefix(r.URL.Path, "/orders/"):
		g.proxyTo(w, r, "orders") // route to a resolved backend
	case r.URL.Path == "/dashboard":
		// aggregate: fan out to two services, merge into one response
		user := g.fetch(r.Context(), "users", "/me")
		orders := g.fetch(r.Context(), "orders", "/recent")
		json.NewEncoder(w).Encode(map[string]any{"user": user, "orders": orders})
	default:
		http.NotFound(w, r)
	}
}

