type Instance struct {
	ID   string
	Addr string
}

// Registry maps a service name to its live instances.
type Registry struct {
	mu       sync.RWMutex
	services map[string][]Instance
}

func NewRegistry() *Registry {
	return &Registry{services: make(map[string][]Instance)}
}

func (r *Registry) Register(name string, inst Instance) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.services[name] = append(r.services[name], inst)
}

// Lookup returns a copy of the live instances for a service.
func (r *Registry) Lookup(name string) []Instance {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return append([]Instance(nil), r.services[name]...)
}

// RoundRobin picks instances evenly using an atomic counter.
type RoundRobin struct{ n uint64 }

func (rr *RoundRobin) Pick(insts []Instance) (Instance, bool) {
	if len(insts) == 0 {
		return Instance{}, false
	}
	i := atomic.AddUint64(&rr.n, 1)
	return insts[int(i)%len(insts)], true
}

func main() {
	reg := NewRegistry()
	reg.Register("payments", Instance{ID: "a", Addr: "10.0.0.1:80"})
	reg.Register("payments", Instance{ID: "b", Addr: "10.0.0.2:80"})
	reg.Register("payments", Instance{ID: "c", Addr: "10.0.0.3:80"})

	var lb RoundRobin
	for i := 0; i < 4; i++ {
		insts := reg.Lookup("payments") // discover live set
		inst, _ := lb.Pick(insts)       // balance across it
		fmt.Println(inst.Addr)
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

type Gateway struct {
	// fetch simulates a call to a resolved backend service.
	fetch func(ctx context.Context, service, path string) any
}

func (g *Gateway) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	switch {
	case strings.HasPrefix(r.URL.Path, "/orders/"):
		// simple routing: forward to the orders backend
		res := g.fetch(r.Context(), "orders", r.URL.Path)
		json.NewEncoder(w).Encode(res)
	case r.URL.Path == "/dashboard":
		// aggregation: fan out to two backends, merge one response
		user := g.fetch(r.Context(), "users", "/me")
		orders := g.fetch(r.Context(), "orders", "/recent")
		json.NewEncoder(w).Encode(map[string]any{"user": user, "orders": orders})
	default:
		http.NotFound(w, r)
	}
}

func main() {
	g := &Gateway{fetch: func(ctx context.Context, service, path string) any {
		return fmt.Sprintf("%s%s", service, path) // stand-in for a real backend call
	}}

	rec := httptest.NewRecorder()
	g.ServeHTTP(rec, httptest.NewRequest("GET", "/dashboard", nil))
	fmt.Print(rec.Body.String())
	// Output: {"orders":"orders/recent","user":"users/me"}
}

