import (
	"sync"
	"time"
)

type Instance struct {
	ID   string
	Addr string
}

// Registry now tracks a last-seen time per instance for TTL health checks.
type Registry struct {
	mu       sync.RWMutex
	services map[string][]Instance
	lastSeen map[string]time.Time // key: name+"/"+id
}

func NewRegistry() *Registry {
	return &Registry{
		services: make(map[string][]Instance),
		lastSeen: make(map[string]time.Time),
	}
}

func (r *Registry) Register(name string, inst Instance) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.services[name] = append(r.services[name], inst)
	r.lastSeen[name+"/"+inst.ID] = time.Now()
}

// Heartbeat refreshes an instance's TTL; a live instance calls this periodically.
func (r *Registry) Heartbeat(name, id string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.lastSeen[name+"/"+id] = time.Now()
}

// Reap deregisters instances whose last heartbeat is older than ttl.
func (r *Registry) Reap(name string, ttl time.Duration) {
	r.mu.Lock()
	defer r.mu.Unlock()
	live := r.services[name][:0]
	for _, inst := range r.services[name] {
		if time.Since(r.lastSeen[name+"/"+inst.ID]) < ttl {
			live = append(live, inst) // keep only fresh instances
		} else {
			delete(r.lastSeen, name+"/"+inst.ID) // deregister stale one
		}
	}
	r.services[name] = live
}

func (r *Registry) Lookup(name string) []Instance {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return append([]Instance(nil), r.services[name]...)
}

