package solution

import "sync/atomic"

// Balancer picks instances in round-robin order using an atomic counter
// so concurrent callers stay evenly balanced.
type Balancer struct {
	n uint64
}

// Next returns the next instance in rotation, or ("", false) if the
// live set is empty (all instances deregistered / unhealthy).
func (b *Balancer) Next(insts []string) (string, bool) {
	if len(insts) == 0 {
		return "", false
	}
	i := atomic.AddUint64(&b.n, 1) // atomic advance, safe under concurrency
	return insts[int(i)%len(insts)], true
}

