package solution

import (
	"context"
	"sync"
)

// Aggregate fans out to every backend call concurrently, propagates ctx
// so a client disconnect cancels the fan-out, and returns the first error.
func Aggregate(ctx context.Context, calls map[string]func(context.Context) (string, error)) (map[string]string, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	var (
		mu      sync.Mutex
		wg      sync.WaitGroup
		results = make(map[string]string)
		firstErr error
	)

	for name, call := range calls {
		wg.Add(1)
		go func(name string, call func(context.Context) (string, error)) {
			defer wg.Done()
			val, err := call(ctx)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				if firstErr == nil {
					firstErr = err
					cancel() // cancel the remaining calls
				}
				return
			}
			results[name] = val
		}(name, call)
	}

	wg.Wait()
	if firstErr != nil {
		return nil, firstErr
	}
	return results, nil
}

