type Instance struct {
	ID   string
	Addr string
}

type Registry struct {
	mu       sync.RWMutex
	services map[string][]Instance
	lastSeen map[string]time.Time
	rr       map[string]*uint64 // per-service round-robin counter
}

func NewRegistry() *Registry {
	return &Registry{
		services: map[string][]Instance{},
		lastSeen: map[string]time.Time{},
		rr:       map[string]*uint64{},
	}
}

func key(name, id string) string { return name + "/" + id }

func (r *Registry) Register(name string, inst Instance) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.services[name] = append(r.services[name], inst)
	r.lastSeen[key(name, inst.ID)] = time.Now()
	if r.rr[name] == nil {
		r.rr[name] = new(uint64)
	}
}

func (r *Registry) Heartbeat(name, id string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.lastSeen[key(name, id)] = time.Now()
}

// Reap deregisters instances whose TTL has expired.
func (r *Registry) Reap(name string, ttl time.Duration) {
	r.mu.Lock()
	defer r.mu.Unlock()
	live := r.services[name][:0]
	for _, inst := range r.services[name] {
		if time.Since(r.lastSeen[key(name, inst.ID)]) < ttl {
			live = append(live, inst)
		} else {
			delete(r.lastSeen, key(name, inst.ID))
		}
	}
	r.services[name] = live
}

// Pick returns the next healthy instance in round-robin order.
func (r *Registry) Pick(name string) (Instance, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	insts := r.services[name]
	if len(insts) == 0 {
		return Instance{}, false
	}
	i := atomic.AddUint64(r.rr[name], 1)
	return insts[int(i)%len(insts)], true
}
